ain_menu:"Terug naar Hoofdmenu",control_badge:"IN CONTROLE",control_win_title:"Je behoudt de controle",control_win_subtitle:"Dat is een overwinning. Erken dit moment van discipline en kracht.",control_btn_commit:"Toewijden aan structuur behouden",control_btn_home:"Terug naar Hoofdmenu",commit_badge:"POSITIEVE TOEWIJDING",commit_title:"Toewijding",commit_subtitle:"Versterk je intentie om op koers te blijven.",commit_why_label:"WAAROM DOE IK DIT?",commit_why_empty:"Voeg je reden toe",commit_why_link:"Beheer →",commit_hold_instruction:"HOUD INGEDRUKT OM TOE TE WIJDEN",commit_success_heading:"Toewijding versterkt",commit_success_body:"Je koos ervoor om in structuur te blijven. Elke bewuste keuze bouwt mentale veerkracht op.",commit_btn_main_menu:"Terug naar Hoofdmenu",dash_resume_ability_score_label:"DAILY RESUME-ABILITY SCORE",score_feedback_high_recovery:"Uitstekende veerkracht vandaag — je had te maken met onderbrekingen en hebt je opnieuw toegewijd.",score_feedback_strong_structure:"Sterke consistentie en controle behouden vandaag.",score_feedback_slips_no_recommit:"Bewustzijn vastgelegd. Herverbind na een slip om je Resume-Ability te oefenen.",score_feedback_low_engagement:"Goed begin. Check later vandaag nog eens in om momentum op te bouwen.",score_feedback_no_activity:"Klaar wanneer jij dat bent. Check in om te beginnen met het oefenen van je Resume-Ability.",quote_screen_label:"CHECK-IN VOLTOOID",quote_btn_home:"TERUG NAAR HOOFDMENU",motivational_quotes:["Je hebt geen perfectie nodig. Je hebt het vermogen nodig om terug te keren.","Bewustzijn verandert een moment in een keuze.","Elke terugkeer versterkt je Resume-Ability.","Vooruitgang gaat verder zodra je opnieuw voor je structuur kiest.","Consistentie groeit één bewuste keuze tegelijk.","Een pauze is geen mislukking. Hervatten is jouw kracht.","Structuur geeft vrijheid; terugkeren geeft meesterschap.","Vertrouw op het proces. Je vermogen om te resetten is altijd binnen bereik.","Kleine bewuste resets stapelen zich op tot blijvende veerkracht.","Blijf verbonden met je waarom en blijf vooruitgaan."],motivation_choice_label:"IK HEB MOTIVATIE NODIG",motivation_choice_heading:"Hoe wil je je motivatie ontvangen?",motivation_choice_sub:"Kies wat op dit moment het beste voor jou werkt.",motivation_btn_audio:"Luister naar Motiverende Audio",motivation_btn_audio_desc:"Vind rust en focus met korte begeleide motivatietracks.",motivation_btn_text:"Lees Motiverende Tekst",motivation_btn_text_desc:"Korte, krachtige woorden om direct perspectief te herwinnen.",motivational_text_label:"MOTIVERENDE FOCUS",motivational_text_btn_next:"Toon een ander bericht",motivational_text_btn_home:"TERUG NAAR HOOFDMENU",motivational_texts:[{title:"Eén beslissing tegelijk",body:"Je hoeft niet de hele dag nu op te lossen. Kies de volgende gestructureerde actie. Eén bewuste keuze is genoeg om de koers van dit moment te veranderen."},{title:"Drang is geen bevel",body:"Een verlangen kan dringend aanvoelen zonder een bevel te zijn. Merk op wat er gebeurt, maak opnieuw contact met je Waarom en kies bewust je volgende stap."},{title:"Vooruitgang blijft behouden",body:"Vooruitgang gaat niet verloren door één moeilijk moment. Resume-Ability begint op het moment dat je besluit terug te keren naar je structuur."},{title:"Pauzeer en adem",body:"Haal diep adem en breek het momentum van de impuls. De hunkering is tijdelijk, maar de kracht van jouw toewijding blijft."},{title:"Eer je grenzen",body:"Je non-negotiables beschermen jouw gemoedsrust en langetermijndoelen. Ze nu naleven is een directe investering in zelfvertrouwen."},{title:"Observeer zonder oordeel",body:"Neem afstand van frustratie. Het observeren van je triggers zonder zelfkritiek geeft je de helderheid die je nodig hebt om op koers te blijven."},{title:"Resume-Ability in actie",body:"Meesterschap betekent niet dat je nooit verleiding voelt. Meesterschap is weten hoe je terugkeert zodra je merkt dat je afdwaalt."},{title:"Kleine resets doen ertoe",body:"Elke keer dat je jouw plan verkiest boven een impuls, wordt je mentale discipline sterker. Je bent in staat dit moment te hanteren."},{title:"De kracht van de volgende maaltijd",body:"Draag een lastig moment niet mee naar de rest van de dag. Reset je focus direct en sluit aan bij je volgende geplande eetvenster."},{title:"Jij hebt de regie",body:"De omgeving en gewoonteloops trekken aan je aandacht, maar de uiteindelijke keuze is altijd aan jou. Kies wat jouw toekomst dient."}],timer_audio_toggle_label:"AUDIO",timer_audio_with:"Met Audio",timer_audio_without:"Zonder Audio",timer_audio_disabled_desc:"Timer loopt zonder audio.",sda_terms_link:"SDA-Terminologie",sda_terms_title:"Super Diet-Ability Begrippen",sda_terms_subtitle:"Begrijp de kernconcepten van Super Diet-Ability.",sda_term_slip_title:"Slip",sda_term_slip_def:"Een moment waarop je buiten je bedoelde structuur raakt. Dit melden helpt je op te merken wat er gebeurde en te oefenen met terugkeren.",sda_term_sz_title:"Gevaarlijke Zone (Slippery Zone)",sda_term_sz_def:"Een situatie of trigger die het makkelijker maakt om van je structuur af te wijken.",sda_term_nn_title:"Non-Negotiable",sda_term_nn_def:"Een persoonlijke toewijding die je hebt besloten te beschermen, zelfs als de dag lastig wordt.",sda_term_ra_title:"Resume-Ability",sda_term_ra_def:"Je vermogen om terug te keren naar je bedoelde structuur na een moeilijk moment of slip.",sda_term_sd_title:"Gestructureerd Dieet (Structured Diet)",sda_term_sd_def:"De eetstructuur die je bewust kiest — inclusief wanneer, wat en hoe je plant te eten.",sda_term_mf_title:"Micro-Vasten (Micro-Fasting)",sda_term_mf_def:"Een geplande periode binnen je Gestructureerd Dieet waarin je bewust niet eet.",sda_btn_close:"Begrepen",sda_btn_home:"Terug naar Hoofdmenu",sda_info_aria:"Meer informatie over dit begrip",sdb_day_mon:"Maandag",sdb_day_tue:"Dinsdag",sdb_day_wed:"Woensdag",sdb_day_thu:"Donderdag",sdb_day_fri:"Vrijdag",sdb_day_sat:"Zaterdag",sdb_day_sun:"Zondag",sdb_day_mon_s